import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused bias addition, scaling, and sigmoid
fused_op_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_op_kernel(const float* input, const float* bias, const float* scale,
                                float* output, int C, int H, int W, int num_elements) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < num_elements) {
        int c = (index / (H * W)) % C;
        float val = input[index] + __ldg(&bias[c]);
        val *= __ldg(&scale[c]);
        output[index] = 1.0f / (1.0f + expf(-val));
    }
}

torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor bias, torch::Tensor scale) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_op_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        output.data_ptr<float>(),
        C, H, W, num_elements
    );

    return output;
}
"""

fused_op_cpp = "torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor bias, torch::Tensor scale);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_op_cpp,
    cuda_sources=fused_op_source,
    functions=['fused_op_cuda'],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, bias_shape, scale_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, padding=kernel_size//2)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.group_norm = nn.GroupNorm(num_groups, out_channels)
        self.fused_op = fused_op

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_op.fused_op_cuda(x, self.bias, self.scale)
        x = self.group_norm(x)
        return x
